"use client";

import { useCallback, useEffect, useState } from "react";
type Member = { id: string; status: string; student: { id: string; name: string | null; email: string; avatar: string | null }; group: { id: string; name: string } };
export default function TeacherStudentsPage() { const [items, setItems] = useState<Member[]>([]); const [error, setError] = useState(""); const load = useCallback(async () => { const r = await fetch("/api/teacher/students", { cache: "no-store" }); const p = await r.json().catch(() => null); if (r.ok) setItems(p.data ?? []); else setError(p?.error ?? "Unable to load learners."); }, []); useEffect(() => { void load(); }, [load]); return <section className="space-y-6"><header><h2 className="text-3xl font-bold">Students</h2><p className="mt-2 text-slate-600">Only learners linked to one of your groups are visible here.</p></header>{error ? <p className="rounded-lg bg-red-50 p-3 text-red-800">{error}</p> : null}{items.length === 0 ? <div className="rounded-2xl border border-dashed bg-white p-8 text-slate-600">No learners yet. Add a learner from a group page.</div> : <div className="overflow-hidden rounded-2xl border bg-white"><table className="w-full text-left text-sm"><thead className="bg-slate-50 text-slate-600"><tr><th className="p-4">Learner</th><th className="p-4">Group</th><th className="p-4">Status</th></tr></thead><tbody>{items.map((item) => <tr key={item.id} className="border-t"><td className="p-4"><p className="font-semibold">{item.student.name ?? item.student.email}</p><p className="text-slate-500">{item.student.email}</p></td><td className="p-4">{item.group.name}</td><td className="p-4">{item.status}</td></tr>)}</tbody></table></div>}</section>; }
